const item = $input.first();
let text = item.json.content[0].text;

text = text.replace(/```json\s*/gi, '');
text = text.replace(/```\s*/gi, '');
text = text.trim();

let ai;
try {
  ai = JSON.parse(text);
} catch (e) {
  ai = { company_name: 'Company', hero: { exists: true, headline: 'Welcome', subtext: '', cta_text: 'Contact', cta_url: '' } };
}

return [{
  json: {
    ...$('On form submission').first().json,
    full_scraped_content: $('Code: Scrape All Pages').first().json.full_scraped_content,
    ai: ai
  }
}];

const item = $input.first();
let html = '';

if (item.json.content && Array.isArray(item.json.content)) {
  const textBlock = item.json.content.find(c => c.type === 'text');
  if (textBlock) html = textBlock.text;
}

html = html.replace(/^```html\s*/i, '').replace(/```\s*$/, '').trim();

return [{
  json: {
    ...$('On form submission').first().json,
    website_html: html
  }
}];

const item = $input.first();
const formData = $('On form submission').first().json;

const html = item.json.website_html || '';
const base64 = Buffer.from(html).toString('base64');

const companyName =
  item.json.company_name ||
  formData['Company Name'] ||
  'company';

const slug = companyName
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '');

return [{
  json: {
    ...formData,
    html_base64: base64,
    company_slug: slug,
    company_name: companyName,
    recipient_email: formData['Your Email'],
    website_url: `https://izu737.github.io/job-sites/${slug}/`
  }
}];

const item = $input.first();
const original = $('On form submission').first().json;
const homepage = item.json.data || '';

// Extract ALL internal links from homepage
const baseUrl = original.company_website || '';
const baseDomain = baseUrl.replace(/^https?:\/\//, '').replace(/\/.*$/, '').replace(/^www\./, '').toLowerCase();

const urlRegex = /https?:\/\/[^\s"'<>\]\)\,]+/g;
const allUrls = (homepage.match(urlRegex) || []);

const excluded = [
  '/login', '/signup', '/register', '/cart', '/checkout',
  '/privacy', '/terms', '/cookie', '/legal', '/cdn-cgi',
  '.jpg', '.jpeg', '.png', '.gif', '.svg', '.css', '.js',
  '.pdf', '.zip', '#', 'mailto:', 'tel:', '/blog/', '/news/',
  '/careers', '/jobs', '/press', 'facebook.com', 'twitter.com',
  'linkedin.com', 'instagram.com', 'youtube.com', 'google.com'
];

const internalLinks = [...new Set(allUrls)]
  .filter(url => {
    const domain = url.replace(/^https?:\/\//, '').replace(/\/.*$/, '').replace(/^www\./, '').toLowerCase();
    if (!domain.includes(baseDomain) && !baseDomain.includes(domain)) return false;
    const lower = url.toLowerCase();
    return !excluded.some(e => lower.includes(e));
  })
  .filter(url => url !== baseUrl && url !== baseUrl + '/')
  .slice(0, 20); // cap at 20 pages

// Scrape every internal page. JINA_API_KEY must be set as an n8n environment variable.
const scrapedPages = [];
for (const url of internalLinks) {
  try {
    const response = await $helpers.httpRequest({
      method: 'GET',
      url: `https://r.jina.ai/${url}`,
      headers: {
        'Authorization': `Bearer ${$env.JINA_API_KEY}`,
        'Accept': 'application/json'
      },
      timeout: 15000
    });
    const content = response.data || response.content || '';
    if (content.length > 300) {
      scrapedPages.push(`\n\n=== PAGE: ${url} ===\n${content.substring(0, 8000)}`);
    }
  } catch (e) {
    // skip failed pages silently
  }
}

const full_content = `=== HOMEPAGE: ${baseUrl} ===\n${homepage.substring(0, 8000)}${scrapedPages.join('')}`;

return [{
  json: {
    ...original,
    full_scraped_content: full_content,
    pages_scraped: scrapedPages.length + 1
  }
}];

const item = $input.first();
const companySlug = $('Code: Base64 Encode + Push to GitHub').first().json.company_slug;

return [{
  json: {
    ...item.json,
    website_url: `https://izu737.github.io/job-sites/${companySlug}/`
  }
}];
